document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('[data-parameter-form]'))return;e.preventDefault();const status=form.querySelector('.parameter-status'),button=form.querySelector('button'),values={};for(const input of form.querySelectorAll('input')){if(input.value!==input.dataset.original){if(input.value===''){status.textContent='Para ajustar um campo, informe um número. Campos vazios não apagam valores.';return;}values[input.name]=Number(input.value);}}if(!Object.keys(values).length){status.textContent='Nenhuma alteração para salvar.';return;}button.disabled=true;status.textContent='Salvando…';try{const response=await fetch('/api/parameters',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:form.dataset.item,date:form.dataset.date,values})}),result=await response.json();if(!response.ok)throw Error(result.error);data=await(await fetch('/data.json')).json();engine=createEngine(data);if(page==='estoque')renderStock(true);else renderMRP();const updated=document.querySelector(`#${page==='estoque'?'stock-bottom':'detail'} .parameter-editor`);if(updated){updated.open=true;updated.querySelector('.parameter-status').textContent='Parâmetros salvos. Cálculos atualizados.';}}catch(error){status.textContent='Não foi possível salvar: '+error.message;button.disabled=false;}});

window.addEventListener('planning:data-changed',async e=>{await recalculatePlanning(e.detail?.message||'Alteração salva. Planejamento recalculado automaticamente.')});
